import { mkdtemp, mkdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { decisionLine, parseRunlog, realityCase, summariseReality } from "./reality";

describe("parseRunlog", () => {
  it("reads the run id and every case row as cli.ts writes them", () => {
    const log = parseRunlog([
      "# Run log", "", "Run 2026-10-10T16:32:00.000Z-reality. Generated by `npm run answer`; not edited by hand.", "",
      "| Case | Result | Outcome | Time | Cost |", "|---|---|---|---|---|",
      "| 1 | ok | acted | 41.2 s | $0.183 |",
      "| 2 | failed at plan: overloaded (attempt 2) | error | 12.0 s | $0.020 |",
      "| 3 | failed outside the flow: ENOENT | error | | |",
      "| 4 | kept from an earlier run | escalated | | |",
    ].join("\n"));
    expect(log.runId).toBe("2026-10-10T16:32:00.000Z-reality");
    expect(log.rows).toEqual([
      { caseName: "1", result: "ok", outcome: "acted", seconds: 41.2, costUsd: 0.183 },
      { caseName: "2", result: "failed at plan: overloaded (attempt 2)", outcome: "error", seconds: 12, costUsd: 0.02 },
      { caseName: "3", result: "failed outside the flow: ENOENT", outcome: "error", seconds: null, costUsd: null },
      { caseName: "4", result: "kept from an earlier run", outcome: "escalated", seconds: null, costUsd: null },
    ]);
  });
});

describe("decisionLine and realityCase", () => {
  it("reads the Decision line and flags escalation and failure", () => {
    const md = "# Parcel lost\n\n**Decision:** HOLD FOR A HUMAN. The desk asks the supervisor to approve a reship.\n**Why:** x";
    expect(decisionLine(md)).toBe("HOLD FOR A HUMAN. The desk asks the supervisor to approve a reship.");
    expect(decisionLine(null)).toBeNull();
    expect(realityCase({ id: "e1", case_id: "7", title: null, status: "success", outcome: "acted", cost_usd: 0.1, duration_ms: 900, answer_md: md, has_card: 1 }))
      .toEqual({ n: "7", caseId: "7", title: "Parcel lost", outcome: "acted", decision: "HOLD FOR A HUMAN. The desk asks the supervisor to approve a reship.",
        escalated: true, failed: false, costUsd: 0.1, durationMs: 900, executionId: "e1" });
  });

  it("summarises outcomes, totals and the run log", () => {
    const base = { n: "1", caseId: "1", title: null, decision: null, executionId: "x" };
    const s = summariseReality([
      { ...base, outcome: "acted", escalated: false, failed: false, costUsd: 0.1, durationMs: 1000 },
      { ...base, outcome: "escalated", escalated: true, failed: false, costUsd: 0.2, durationMs: 2000 },
      { ...base, outcome: "error", escalated: false, failed: true, costUsd: null, durationMs: null },
    ], { runId: "r", rows: Array.from({ length: 4 }, (_, i) => ({ caseName: String(i), result: "ok", outcome: null, seconds: null, costUsd: null })) }, true);
    expect(s).toEqual({ total: 4, finished: 2, cases: 3, byOutcome: { acted: 1, escalated: 1, error: 1 }, escalated: 1, failed: 1,
      costUsd: 0.3, durationMs: 3000, runId: "r", hasIndex: true });
  });
});

// The import end to end, on a temp ANSWERS/ tree shaped like `npm run reality` output, into a temp SQLite file.
describe("ANSWERS/ import", () => {
  let root: string;
  const trace = (outcome: string, extra: Record<string, unknown> = {}) => ({
    version: 1, runId: "2026-10-10T16:32:00.000Z-reality", caseId: null, flowId: "default-incident", mode: "reality",
    events: [
      { t: 0, kind: "run_start", title: "Case title from the trace", inputs: [] },
      { t: 9, kind: "run_end", outcome, totalCostUsd: 0.12, totalLatencyMs: 40100, nextAction: null, ...extra },
    ],
  });
  const write = async (rel: string, text: string) => {
    await mkdir(path.dirname(path.join(root, rel)), { recursive: true });
    await writeFile(path.join(root, rel), text);
  };

  beforeAll(async () => {
    root = await mkdtemp(path.join(tmpdir(), "reality-"));
    process.env.CONSOLE_REPO_ROOT = root;
    process.env.CONSOLE_DB_PATH = path.join(root, "runs", "console.db");
    // 1: a finished case with a recorded message.
    await write("ANSWERS/1/trace.json", JSON.stringify(trace("acted", { nextAction: { recipient: "Dispatch", channel: "Email", message: "m" } })));
    await write("ANSWERS/1/ANSWER.md", "# Lost parcel\n\n**Decision:** ACT. The desk emails dispatch.\n");
    await write("ANSWERS/1/REASONING.md", "# Reasoning\n");
    await write("ANSWERS/1/result.json", JSON.stringify({ outcome: "acted", outbox: [{ action: { recipient: "Dispatch", channel: "Email", kind: "k", purpose: "p", message: "m" }, status: "recorded", note: "" }] }));
    // 2: held for a person (decision card in result.json).
    await write("ANSWERS/2/trace.json", JSON.stringify(trace("escalated")));
    await write("ANSWERS/2/ANSWER.md", "# Gate code\n\n**Decision:** HOLD FOR A HUMAN. A supervisor decides.\n");
    await write("ANSWERS/2/result.json", JSON.stringify({ outcome: "escalated", outbox: [], card: { routeTo: "Supervisor", summary: "s", fallback: "f", options: [] } }));
    // 3: failed outside the flow: only the runner's failure answer, no trace.
    await write("ANSWERS/3/ANSWER.md", "# 3\n\n**Decision:** SYSTEM FAILURE: HANDED TO A HUMAN\n");
    await write("ANSWERS/3/REASONING.md", "# Reasoning: 3\n\nThe run failed before any analysis: ENOENT: no such file\n");
    // 10: trace.json cut off by a killed run; result.json still has the trace.
    await write("ANSWERS/10/trace.json", "{\"version\":1,\"events\":[");
    await write("ANSWERS/10/result.json", JSON.stringify({ outcome: "no_action", outbox: [], trace: trace("no_action") }));
    await write("ANSWERS/10/ANSWER.md", "# Quiet case\n\n**Decision:** NO ACTION NEEDED NOW. Nothing is owed.\n");
    await write("ANSWERS/RUNLOG.md", "Run 2026-10-10T16:32:00.000Z-reality. Generated by `npm run answer`.\n\n| Case | Result | Outcome | Time | Cost |\n|---|---|---|---|---|\n| 1 | ok | acted | 40.1 s | $0.120 |\n| 2 | ok | escalated | 40.1 s | $0.120 |\n| 3 | failed outside the flow: ENOENT | error | | |\n| 10 | ok | no_action | 40.1 s | $0.120 |\n| 11 | not run | error | | |\n");
    await write("ANSWERS/INDEX.md", "# Results index\n");
    await write("ANSWERS/case-history.jsonl", "{}\n");
  });
  afterAll(async () => {
    delete process.env.CONSOLE_REPO_ROOT;
    delete process.env.CONSOLE_DB_PATH;
    await rm(root, { recursive: true, force: true });
  });

  it("imports every case folder as dataset reality, origin answers, including failures", async () => {
    const { importAnswers } = await import("./importer");
    const { realityReport } = await import("./reality");
    expect(await importAnswers()).toBe(4);
    const { cases, summary, runlog } = await realityReport();
    expect(cases.map((c) => [c.n, c.outcome, c.escalated, c.failed, c.costUsd, c.durationMs])).toEqual([
      ["1", "acted", false, false, 0.12, 40100],
      ["2", "escalated", true, false, 0.12, 40100],
      ["3", "error", false, true, null, null],
      ["10", "no_action", false, false, 0.12, 40100],
    ]);
    expect(cases[0]).toMatchObject({ caseId: "1", title: "Case title from the trace", decision: "ACT. The desk emails dispatch." });
    expect(cases[2].title).toBe("3");
    expect(summary).toMatchObject({ total: 5, finished: 3, cases: 4, failed: 1, escalated: 1, hasIndex: true, runId: "2026-10-10T16:32:00.000Z-reality" });
    expect(runlog?.rows).toHaveLength(5);

    const { getExecution } = await import("./store");
    const failed = getExecution(cases[2].executionId!);
    expect(failed).toMatchObject({ dataset: "reality", origin: "answers", status: "error", error: "ENOENT: no such file", trace: null });
    const first = getExecution(cases[0].executionId!);
    expect(first?.outbox).toHaveLength(1);
    expect(first?.nextAction).toBe("Email → Dispatch");
  });

  it("is idempotent, re-imports on change, and drops folders that are gone", async () => {
    const { importAnswers, refreshAnswersIfChanged } = await import("./importer");
    const { realityReport, realityFiles } = await import("./reality");
    expect(await importAnswers()).toBe(4);
    expect(await refreshAnswersIfChanged()).toBe(false);
    await rm(path.join(root, "ANSWERS", "3"), { recursive: true });
    expect(await refreshAnswersIfChanged()).toBe(true);
    expect((await realityReport()).cases.map((c) => c.n)).toEqual(["1", "2", "10"]);
    expect(await realityFiles("1")).toEqual({ answerMd: expect.stringContaining("Lost parcel"), reasoningMd: "# Reasoning\n" });
    expect(await realityFiles("../1")).toBeNull();
    expect(await realityFiles("3")).toBeNull();
  });
});
